import csv
import io


def decode_table(text, delimiter=","):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not isinstance(delimiter, str):
        raise TypeError("delimiter must be a string")
    if len(delimiter) != 1:
        raise ValueError("delimiter must be one character")

    try:
        parsed = csv.reader(io.StringIO(text), delimiter=delimiter, strict=True)
        rows = [list(row) for row in parsed if row]
    except csv.Error as exc:
        raise ValueError("malformed delimited text") from exc

    if not rows:
        return []
    width = len(rows[0])
    if any(len(row) != width for row in rows[1:]):
        raise ValueError("rows have inconsistent widths")
    return rows
```

