import unittest

from solution import decode_table


class DecodeTableTests(unittest.TestCase):
    def test_basic_csv_and_independent_rows(self):
        result = decode_table("a,b\n1,2\n3,4")
        self.assertEqual(result, [["a", "b"], ["1", "2"], ["3", "4"]])
        self.assertIsNot(result[0], result[1])
        result[0][0] = "changed"
        self.assertEqual(result[1], ["1", "2"])

    def test_standard_csv_quoting(self):
        text = 'name,detail\n"alpha","has, comma"\n"quote","said ""hello"""'
        self.assertEqual(
            decode_table(text),
            [["name", "detail"], ["alpha", "has, comma"], ["quote", 'said "hello"']],
        )

    def test_custom_delimiter_and_quoted_newline(self):
        text = 'a;"line one\nline two"\n b ; c '
        self.assertEqual(
            decode_table(text, ";"),
            [["a", "line one\nline two"], [" b ", " c "]],
        )

    def test_ignores_physical_blank_lines_and_all_whitespace_rows(self):
        text = "\n\r\n   \n\t,  \n a , b \n\n c , d \n"
        self.assertEqual(decode_table(text), [[" a ", " b "], [" c ", " d "]])
        self.assertEqual(decode_table("\n   \n\t, \t\n"), [])

    def test_preserves_whitespace_in_retained_cells(self):
        self.assertEqual(
            decode_table('  a  ," b ", c\t\n 1 , 2 , 3 '),
            [["  a  ", " b ", " c\t"], [" 1 ", " 2 ", " 3 "]],
        )

    def test_empty_text(self):
        self.assertEqual(decode_table(""), [])

    def test_inconsistent_retained_widths(self):
        with self.assertRaises(ValueError):
            decode_table("a,b\n1,2,3")
        with self.assertRaises(ValueError):
            decode_table("a,b\n   \n1")

    def test_malformed_quoting(self):
        for text in ('a,"unterminated', 'a,"b"oops,c'):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    decode_table(text)

    def test_argument_validation(self):
        for bad in (None, b"a,b", 1, ["a"]):
            with self.subTest(text=bad):
                with self.assertRaises(TypeError):
                    decode_table(bad)
        for bad in (None, 1, b","):
            with self.subTest(delimiter=bad):
                with self.assertRaises(TypeError):
                    decode_table("", bad)
        for bad in ("", ",,", "ab"):
            with self.subTest(delimiter=bad):
                with self.assertRaises(ValueError):
                    decode_table("", bad)


if __name__ == "__main__":
    unittest.main()

